const XLSX = require('xlsx');
const wb = XLSX.readFile('testbed/data/travel_expenses.xlsx');
const ws = wb.Sheets['Travel'];

// Read existing data
const existing = XLSX.utils.sheet_to_json(ws, { header: 1 });
const nextRow = existing.length; // 0-indexed, header is row 0

// New bookings to add (using patterns from existing data)
const newBookings = [
  // 1. Flight: FL658038, JFK → LHR
  ['FL658038', 'cc_2d338641', 'Flight', 'JFK → LHR', '', 'confirmed', 0],
  // 2. Hotel: Desert Palm Hotel, Las Vegas (from existing inventory, aligned with Las Vegas dates)
  ['HR-FL65A', 'cc_2d338641', 'Hotel', 'Desert Palm Hotel, Las Vegas', '2026-09-18 to 2026-09-21', 'confirmed', 298],
  // 3. Car Rental: Las Vegas McCarran International Airport
  ['CR-FL65B', 'cc_2d338641', 'Car Rental', 'Las Vegas McCarran International Airport → Las Vegas McCarran International Airport', '2026-09-18 to 2026-09-21', 'confirmed', 138],
];

// Append rows
newBookings.forEach((row, i) => {
  const rowIdx = nextRow + i;
  row.forEach((val, colIdx) => {
    const cellRef = XLSX.utils.encode_cell({ r: rowIdx, c: colIdx });
    ws[cellRef] = { t: typeof val === 'number' ? 'n' : 's', v: val };
  });
});

// Update the sheet range
const range = XLSX.utils.decode_range(ws['!ref']);
range.e.r = nextRow + newBookings.length - 1;
ws['!ref'] = XLSX.utils.encode_range(range);

// Write back
XLSX.writeFile(wb, 'testbed/data/travel_expenses.xlsx');
console.log('✅ Successfully added', newBookings.length, 'new bookings.');

// Verify by reading back
const wb2 = XLSX.readFile('testbed/data/travel_expenses.xlsx');
const ws2 = wb2.Sheets['Travel'];
const allData = XLSX.utils.sheet_to_json(ws2, { header: 1 });
console.log('\nTotal rows (incl. header):', allData.length);
console.log('\n--- New bookings added ---');
allData.slice(-3).forEach(row => console.log(row.join(' | ')));
"

